<script setup lang="ts">import {ref,computed,onMounted} from 'vue';import {spaces} from '../stores/spaces';import {models} from '../stores/models';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const selected=ref('demo-space'),model=ref('demo-model'),name=ref(''),description=ref('独立均匀分布；物理单位与所选模型一致。'),ranges=ref("factor_id,low,high\nflow,18,30\ninlet,25,33\nload,0.45,0.95\nfan,30,50\napproach,3,8\neff,65,85");const {error,busy,act}=useTask();onMounted(()=>Promise.all([spaces.load(),models.load()]));const space=computed(()=>spaces.items.value.find(r=>r.id===selected.value));function submit(){act(async()=>{const r=await spaces.create({name:name.value,model_id:model.value,description:description.value,ranges_csv:ranges.value});selected.value=r.id;name.value=''})}</script><template><PageHeading index="02 / 因子空间" title="每个范围，都参与了敏感度的含义。" note="各因子独立均匀分布，范围必须正宽且完整覆盖模型；归一坐标u∈[0,1]按物理范围映射。改变范围，不能沿用原排名。"/><div class="two-col"><section><label>因子空间<select v-model="selected"><option v-for="r in spaces.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><template v-if="space"><h2>{{space.name}}</h2><div class="range-row" v-for="f in space.ranges" :key="f.factor_id"><b>{{f.factor_id}}</b><span>{{f.low}}</span><i></i><span>{{f.high}}</span></div><p class="method-note">{{space.description}}<br>图示各自范围端点；不同单位不作长度大小比较。</p></template></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>锁定物理范围</h2><label>空间名称<input v-model="name" required minlength="2"></label><label>对应模型<select v-model="model"><option v-for="r in models.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>物理范围CSV<textarea v-model="ranges" rows="9" required></textarea></label><label>范围假设<input v-model="description"></label><Notice :message="error"/><button :disabled="busy">保存因子空间</button></form></div></template>
